package com.swarainstitute.app;
import org.json.*;
import java.util.*;
public class NativeTest {
    static int passed=0;
    interface Checked {void run()throws Exception;}
    static void test(String name,Checked fn)throws Exception{fn.run();passed++;System.out.println("PASS "+name);}
    static void check(boolean b){if(!b)throw new AssertionError();}
    static void rejects(Checked fn)throws Exception{try{fn.run();}catch(Exception e){return;}throw new AssertionError("Expected rejection");}
    static JSONObject obj(String s)throws Exception{return new JSONObject(s);}
    static JSONObject fixture()throws Exception{
        JSONObject db=Database.empty();db.getJSONArray("registrations").put(obj("{id:reg,studentId:s,amount:500,date:'2026-10-01',mode:UPI,receipt:REG001,status:Paid}"));db.getJSONArray("trainers").put(obj("{id:t,name:Teacher,mobile:'9000000000',expertise:Vocals,availability:Tuesday,commission:25,status:Active}"));db.getJSONArray("trainers").put(obj("{id:t2,name:Other,mobile:'9000000001',expertise:Guitar,availability:Friday,commission:10,status:Active}"));
        db.getJSONArray("courses").put(obj("{id:c,name:Vocals,category:Beginner,subcategory:Voice,feeType:Monthly,fee:6000,sessions:12,status:Active}"));
        db.getJSONArray("students").put(obj("{id:s,name:Student,age:14,mobile:'9000000002',location:Pune,trainerId:t,courseIds:[c],status:Active,enrollmentDate:'2026-10-01',feePlan:Private}"));db.getJSONArray("students").put(obj("{id:s2,name:OtherStudent,age:16,mobile:'9000000003',location:Pune,trainerId:t2,courseIds:[c],status:Active,enrollmentDate:'2026-10-01'}"));
        db.getJSONArray("artists").put(obj("{id:a,name:Artist,mobile:'9000000004',expertise:Tabla,category:Instrumentalist,availability:Weekend,status:Active,payoutExpectation:3000}"));
        db.getJSONArray("sessions").put(obj("{id:ss,studentId:s,trainerId:t,courseId:c,plannedDate:'2026-10-02',actualDate:'2026-10-02',status:Completed,attendance:Present}"));
        db.getJSONArray("fees").put(obj("{id:f,studentId:s,courseId:c,amount:6000,discount:500,dueDate:'2026-10-02',payments:[{id:p,amount:2000,date:'2026-10-01',mode:UPI,receipt:R001}]}"));
        db.getJSONArray("events").put(obj("{id:e,name:Concert,date:'2026-10-02',duration:2,durationUnit:Days,organizer:Host,status:Planned,artistIds:[a],studentIds:[s],trainerIds:[t],collections:5000,organizerCharge:12000,organizerReceived:6000,expenses:[{id:x,category:'Artist payout',artistId:a,amount:3000,date:'2026-10-01',description:Accompaniment}]}"));Database.validate(db);return db;
    }
    public static void main(String[] args)throws Exception{
        JSONObject db=fixture();
        test("Valid requirement fixture",()->Database.validate(db));
        test("Trainer sees own students only",()->check(Database.view(db,"Trainer","t").getJSONArray("students").length()==1));
        test("Trainer cannot see fee ledger",()->check(Database.view(db,"Trainer","t").getJSONArray("fees").length()==0));
        test("Trainer cannot see event finance",()->check(!Database.view(db,"Trainer","t").getJSONArray("events").getJSONObject(0).has("organizerCharge")));
        test("Trainer receives own commission estimate",()->check(Database.view(db,"Trainer","t").getJSONArray("trainers").getJSONObject(0).getJSONArray("commissionReceipts").getJSONObject(0).getDouble("commission")==500));
        test("Parent sees own student and fees only",()->{JSONObject v=Database.view(db,"Student / Parent","s");check(v.getJSONArray("students").length()==1);check(v.getJSONArray("fees").length()==1);check(!v.getJSONArray("trainers").getJSONObject(0).has("commission"));});
        test("Artist sees own profile and payout only",()->{JSONObject v=Database.view(db,"Artist","a");check(v.getJSONArray("students").length()==0);check(v.getJSONArray("events").getJSONObject(0).getJSONArray("ownPayouts").length()==1);check(!v.getJSONArray("events").getJSONObject(0).has("expenses"));});
        test("Finance cannot modify student profile",()->{JSONObject v=Database.view(db,"Finance","");v.getJSONArray("students").getJSONObject(0).put("name","Attack");rejects(()->Database.merge(db,v,"Finance",""));});
        test("Trainer cannot inject fee data",()->{JSONObject v=Database.view(db,"Trainer","t");v.getJSONArray("fees").put(db.getJSONArray("fees").getJSONObject(0));rejects(()->Database.merge(db,v,"Trainer","t"));});
        test("Student cannot change attendance",()->{JSONObject v=Database.view(db,"Student / Parent","s");v.getJSONArray("sessions").getJSONObject(0).put("notes","Injected");rejects(()->Database.merge(db,v,"Student / Parent","s"));});
        test("Trainer can update own session notes",()->{JSONObject v=Database.view(db,"Trainer","t");v.getJSONArray("sessions").getJSONObject(0).put("notes","Scales");JSONObject result=Database.merge(db,v,"Trainer","t");check(Database.find(result,"sessions","ss").getString("notes").equals("Scales"));check(result.getJSONArray("students").length()==2);check(result.getJSONArray("fees").length()==1);});
        test("Trainer cannot edit a foreign session",()->{JSONObject v=Database.view(db,"Trainer","t");v.getJSONArray("sessions").getJSONObject(0).put("trainerId","t2");rejects(()->Database.merge(db,v,"Trainer","t"));});
        test("Artist can edit own availability",()->{JSONObject v=Database.view(db,"Artist","a");v.getJSONArray("artists").getJSONObject(0).put("availability","Monday");check(Database.find(Database.merge(db,v,"Artist","a"),"artists","a").getString("availability").equals("Monday"));});
        test("Artist cannot change own identity",()->{JSONObject v=Database.view(db,"Artist","a");v.getJSONArray("artists").getJSONObject(0).put("name","Other");rejects(()->Database.merge(db,v,"Artist","a"));});
        test("Recorded payment cannot be edited",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("fees").getJSONObject(0).getJSONArray("payments").getJSONObject(0).put("amount",100);rejects(()->Database.merge(db,v,"Owner",""));});
        test("Finance can append a receipt",()->{JSONObject v=Database.view(db,"Finance","");v.getJSONArray("fees").getJSONObject(0).getJSONArray("payments").put(obj("{id:p2,amount:1000,date:'2026-10-02',mode:Cash,receipt:R002}"));check(Database.merge(db,v,"Finance","").getJSONArray("fees").getJSONObject(0).getJSONArray("payments").length()==2);});
        test("Overpayment is rejected natively",()->{JSONObject v=Database.view(db,"Finance","");v.getJSONArray("fees").getJSONObject(0).getJSONArray("payments").put(obj("{id:p2,amount:9000,date:'2026-10-02',mode:Cash,receipt:R002}"));rejects(()->Database.merge(db,v,"Finance",""));});
        test("Duplicate receipt rejected natively",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("fees").getJSONObject(0).getJSONArray("payments").put(obj("{id:p2,amount:1000,date:'2026-10-02',mode:Cash,receipt:R001}"));rejects(()->Database.merge(db,v,"Owner",""));});
        test("Parent sees own registration payment",()->check(Database.view(db,"Student / Parent","s").getJSONArray("registrations").length()==1));
        test("Finance can record a registration payment",()->{JSONObject v=Database.view(db,"Finance","");v.getJSONArray("registrations").put(obj("{id:reg2,studentId:s2,amount:750,date:'2026-10-02',mode:Cash,receipt:REG002,status:Paid}"));check(Database.merge(db,v,"Finance","").getJSONArray("registrations").length()==2);});
        test("Zero registration payment is rejected",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("registrations").put(obj("{id:reg2,studentId:s2,amount:0,date:'2026-10-02',mode:Cash,receipt:REG002,status:Paid}"));rejects(()->Database.merge(db,v,"Owner",""));});
        test("Registration receipt cannot duplicate a fee receipt",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("registrations").put(obj("{id:reg2,studentId:s2,amount:750,date:'2026-10-02',mode:Cash,receipt:R001,status:Paid}"));rejects(()->Database.merge(db,v,"Owner",""));});
        test("Recorded registration payment cannot be edited",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("registrations").getJSONObject(0).put("amount",1);rejects(()->Database.merge(db,v,"Owner",""));});
        test("Student references prevent orphan deletion",()->{JSONObject v=Database.view(db,"Owner","");v.put("students",new JSONArray());rejects(()->Database.merge(db,v,"Owner",""));});
        test("Historical session survives trainer reassignment",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("students").getJSONObject(0).put("trainerId","t2");check(Database.merge(db,v,"Owner","").getJSONArray("sessions").getJSONObject(0).getString("trainerId").equals("t"));});
        test("Cannot create session with unassigned trainer",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("sessions").put(obj("{id:new,studentId:s,trainerId:t2,courseId:c,plannedDate:'2026-10-03',status:Planned}"));rejects(()->Database.merge(db,v,"Owner",""));});
        test("New institute data can be committed atomically",()->check(Database.merge(Database.empty(),Database.copy(db),"Owner","").getJSONArray("students").length()==2));
        test("Recorded expense cannot be deleted",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("events").getJSONObject(0).put("expenses",new JSONArray());rejects(()->Database.merge(db,v,"Owner",""));});
        test("Duration unit is validated",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("events").getJSONObject(0).put("durationUnit","Hours");rejects(()->Database.merge(db,v,"Owner",""));});
        test("Duplicate student profile is rejected",()->{JSONObject v=Database.view(db,"Owner","");JSONObject duplicate=Database.copy(v.getJSONArray("students").getJSONObject(0));duplicate.put("id","duplicate-student");v.getJSONArray("students").put(duplicate);rejects(()->Database.merge(db,v,"Owner",""));});
        test("Duplicate trainer profile is rejected",()->{JSONObject v=Database.view(db,"Owner","");JSONObject duplicate=Database.copy(v.getJSONArray("trainers").getJSONObject(0));duplicate.put("id","duplicate-trainer");v.getJSONArray("trainers").put(duplicate);rejects(()->Database.merge(db,v,"Owner",""));});
        test("Artist category is required",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("artists").getJSONObject(0).remove("category");rejects(()->Database.merge(db,v,"Owner",""));});
        test("Guardian mobile number is validated",()->{JSONObject v=Database.view(db,"Owner","");v.getJSONArray("students").getJSONObject(0).put("guardianMobile","invalid");rejects(()->Database.merge(db,v,"Owner",""));});
        test("Duplicate work packet name is rejected",()->{JSONObject v=Database.view(db,"Owner","");JSONObject duplicate=Database.copy(v.getJSONArray("courses").getJSONObject(0));duplicate.put("id","duplicate-course");v.getJSONArray("courses").put(duplicate);rejects(()->Database.merge(db,v,"Owner",""));});
        test("Duplicate concert name and date is rejected",()->{JSONObject v=Database.view(db,"Owner","");JSONObject duplicate=Database.copy(v.getJSONArray("events").getJSONObject(0));duplicate.put("id","duplicate-event");v.getJSONArray("events").put(duplicate);rejects(()->Database.merge(db,v,"Owner",""));});
        test("Audit history cannot be replaced by submitted data",()->{JSONObject prior=Database.copy(db);Database.audit(prior,"owner","Original");JSONObject v=Database.view(prior,"Owner","");v.put("audit",new JSONArray());check(Database.merge(prior,v,"Owner","").getJSONArray("audit").length()==1);});
        test("Accounts require matching linked role",()->rejects(()->Database.validateAccount(db,"Trainer","a")));
        JSONObject account=SecureStore.account("owner","123456","Owner","");
        test("PIN is salted and hashed",()->{check(!account.toString().contains("123456"));check(SecureStore.verify(account,"123456"));check(!SecureStore.verify(account,"654321"));});
        test("Short PIN rejected",()->rejects(()->SecureStore.account("owner","1234","Owner","")));
        JSONObject root=new JSONObject().put("state",db).put("accounts",new JSONArray().put(account));String backup=SecureStore.backup(root,"a-strong-backup-password");
        test("Backup encrypts names and PIN hashes",()->{check(!backup.contains("Teacher"));check(!backup.contains(account.getString("hash")));});
        test("Backup decrypts exact original state",()->check(Database.equal(root,SecureStore.restore(backup,"a-strong-backup-password"))));
        test("Wrong backup password fails",()->rejects(()->SecureStore.restore(backup,"wrong-backup-password")));
        test("Modified backup ciphertext fails authentication",()->{JSONObject b=new JSONObject(backup);byte[] data=Base64.getDecoder().decode(b.getString("data"));data[3]^=1;b.put("data",Base64.getEncoder().encodeToString(data));rejects(()->SecureStore.restore(b.toString(),"a-strong-backup-password"));});
        String importText=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(args[1])),java.nio.charset.StandardCharsets.UTF_8);JSONObject importPayload=new JSONObject(importText);JSONObject imported=StudentImport.merge(Database.empty().put("institute","Ramashree Gurukul"),importPayload);
        test("Ramashree student import contains 94 valid profiles",()->{Database.validate(imported);check(imported.getJSONArray("students").length()==94);check(imported.getJSONArray("students").getJSONObject(0).getString("name").equals("Tanya Wells"));});
        test("Ramashree import preserves status counts",()->{int active=0,paused=0,dropped=0;JSONArray students=imported.getJSONArray("students");for(int i=0;i<students.length();i++){String status=students.getJSONObject(i).getString("status");if(status.equals("Active"))active++;if(status.equals("Paused"))paused++;if(status.equals("Dropped"))dropped++;}check(active==60&&paused==18&&dropped==16);});
        test("Ramashree import is idempotent",()->check(StudentImport.merge(imported,importPayload).getJSONArray("students").length()==94));
        test("Ramashree import preserves an existing matching student",()->{JSONObject existing=Database.empty().put("institute","Ramashree Gurukul");existing.getJSONArray("students").put(new JSONObject().put("id","real-tanya").put("name","Tanya Wells").put("age",25).put("mobile","9000000000").put("location","Mumbai").put("courseIds",new JSONArray().put("real-course")).put("trainerId","real-trainer").put("status","Active").put("enrollmentDate","2026-01-01"));existing.getJSONArray("trainers").put(new JSONObject().put("id","real-trainer").put("name","Teacher").put("mobile","9000000001").put("expertise","Vocals").put("availability","Weekdays").put("commission",0).put("status","Active"));existing.getJSONArray("courses").put(new JSONObject().put("id","real-course").put("name","Vocals").put("category","Class").put("subcategory","Vocals").put("feeType","Monthly").put("fee",0).put("sessions",1).put("status","Active"));check(StudentImport.merge(existing,importPayload).getJSONArray("students").length()==94);});
        JSONObject roleViews=new JSONObject();for(String[] pair:new String[][]{{"Owner",""},{"Trainer","t"},{"Artist","a"},{"Student / Parent","s"},{"Finance",""},{"Admin",""}})roleViews.put(pair[0],new JSONObject().put("state",Database.view(db,pair[0],pair[1])).put("username",pair[0].toLowerCase(Locale.ROOT)).put("role",pair[0]).put("entityId",pair[1]));java.nio.file.Files.write(java.nio.file.Paths.get(args[0]),roleViews.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));
        System.out.println(passed+" native permission, validation and cryptography tests passed.");
    }
}
